import{G as e,K as t,n,ot as r}from"./chunks/framework.BZpZOnGD.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"documentalist-lab/generate-sample-content/01-generate-documents.md","filePath":"documentalist-lab/generate-sample-content/01-generate-documents.md"}`),a={name:`documentalist-lab/generate-sample-content/01-generate-documents.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<div class="info custom-block"><p class="custom-block-title">🎬 The Story</p><p><em>The previous lab gave you a map of the territory. Now you need content to work with.</em></p><p><em>You&#39;ll generate a personal set of 5 fictional employees — unique to you — whose HR documents need to be stored in the repository. Each employee has 8 categories of documents, from their original job application all the way through to exit notes.</em></p><p><em>You&#39;ll run a script to generate realistic sample documents locally, then ask Bob to upload them to the repository with the correct metadata. It should be straightforward — but you&#39;ll make a few mistakes along the way. Those mistakes will be the challenge for the next lab.</em></p></div><h2 id="🎯-what-you-will-learn" tabindex="-1">🎯 What You Will Learn <a class="header-anchor" href="#🎯-what-you-will-learn" aria-label="Permalink to “🎯 What You Will Learn”">​</a></h2><p>By the end of this lab, you will be able to:</p><ul><li>Understand the <strong>HR document taxonomy</strong> — 8 categories covering the full employee lifecycle.</li><li>Use the <strong><code>generate_hr_documents.py</code></strong> script to create a <strong>personal, isolated</strong> set of HR documents.</li><li>Ask Bob to <strong>upload documents to the repository</strong> using the MCP tool <code>create_document</code> with correct metadata.</li><li>Understand how <strong><code>DocType</code>, <code>EmployeeID</code>, <code>Department</code></strong> properties are set at creation time.</li><li><strong>Verify</strong> that documents were created correctly using the MCP tools <code>lookup_documents_by_name</code> and <code>get_document_properties</code>.</li></ul><h2 id="🔧-mcp-tools-used" tabindex="-1">🔧 MCP Tools Used <a class="header-anchor" href="#🔧-mcp-tools-used" aria-label="Permalink to “🔧 MCP Tools Used”">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What It Does</th></tr></thead><tbody><tr><td><code>determine_class</code></td><td>Confirms the <code>HRDocument</code> class identifier</td></tr><tr><td><code>get_class_property_descriptions</code></td><td>Shows which properties to set on each document</td></tr><tr><td><code>create_document</code></td><td>Uploads a document with content and metadata</td></tr><tr><td><code>lookup_documents_by_name</code></td><td>Verifies a document was created</td></tr><tr><td><code>get_document_properties</code></td><td>Confirms properties were set correctly</td></tr></tbody></table><h2 id="📋-the-situation" tabindex="-1">📋 The Situation <a class="header-anchor" href="#📋-the-situation" aria-label="Permalink to “📋 The Situation”">​</a></h2><p>You need to create sample HR documents to work with, but you&#39;re not sure how the generation script works or what it will create. You ask Bob to explain the code and the process.</p><h2 id="💬-prompt-to-bob" tabindex="-1">💬 Prompt to Bob <a class="header-anchor" href="#💬-prompt-to-bob" aria-label="Permalink to “💬 Prompt to Bob”">​</a></h2><ol><li><p>Start a new task in IBM Bob by clicking the <code>+</code> sign on top of the Bob chat panel.</p></li><li><p>Click the <strong>+</strong> at the bottom left of the chat input, select <strong>Agent</strong> under <strong>Modes</strong>, and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I need to generate sample HR documents for this lab. Can you explain </span></span>
<span class="line"><span>how the generate_hr_documents.py script works? What will it create, what </span></span>
<span class="line"><span>are the parameters I can provide and can you run it for me?</span></span></code></pre></div></li><li><p>When asked to provide your last name, enter your last name and mention that you want the script to seed some missclassifications:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Use DUPONT as last name and use the seed-miclassification flag</span></span></code></pre></div></li></ol><h2 id="🔍-what-bob-does-behind-the-scenes" tabindex="-1">🔍 What Bob Does Behind the Scenes <a class="header-anchor" href="#🔍-what-bob-does-behind-the-scenes" aria-label="Permalink to “🔍 What Bob Does Behind the Scenes”">​</a></h2><ul><li>Reads the script&#39;s docstring and help text</li><li>Explains the multi-user isolation approach</li><li>Offers to run the script on your behalf with your last name</li><li>Seed missclassifications in the documents</li></ul><h2 id="✅-expected-output-from-bob" tabindex="-1">✅ Expected Output from Bob <a class="header-anchor" href="#✅-expected-output-from-bob" aria-label="Permalink to “✅ Expected Output from Bob”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Done. Here&#39;s a summary of what was generated and what the script does.</p><hr><h4 id="how-generate-hr-documents-py-works" tabindex="-1">How <code>generate_hr_documents.py</code> works <a class="header-anchor" href="#how-generate-hr-documents-py-works" aria-label="Permalink to “How generate_hr_documents.py works”">​</a></h4><hr><h5 id="what-it-creates" tabindex="-1">What it creates <a class="header-anchor" href="#what-it-creates" aria-label="Permalink to “What it creates”">​</a></h5><p><strong>55 text files</strong> in <code>HR_DUPONT/</code>, organised into one sub-folder per employee, each with 8 sub-folders (one per document category):</p><table tabindex="0"><thead><tr><th>Folder</th><th>Document type</th></tr></thead><tbody><tr><td><code>01_Recruitment</code></td><td>Job Application, Interview Notes</td></tr><tr><td><code>02_Employment_Contract</code></td><td>Employment Contract</td></tr><tr><td><code>03_Personal_Administration</code></td><td>ID Documents, Personal Info</td></tr><tr><td><code>04_Payroll</code></td><td>Payslip, Salary Info</td></tr><tr><td><code>05_Performance</code></td><td>Performance Review</td></tr><tr><td><code>06_Training</code></td><td>Training Record</td></tr><tr><td><code>07_Disciplinary</code></td><td>Disciplinary Record</td></tr><tr><td><code>08_Exit</code></td><td>Exit Notes</td></tr></tbody></table><p>Each file also contains a <strong>metadata comment block</strong> at the bottom specifying the <code>HRDocument</code> class properties (EmployeeID, FirstName, LastName, DocType, Department, etc.) that should be set when uploading to the repository.</p><hr><h5 id="multi-user-isolation" tabindex="-1">Multi-user isolation <a class="header-anchor" href="#multi-user-isolation" aria-label="Permalink to “Multi-user isolation”">​</a></h5><p>Your last name (<code>DUPONT</code>) is hashed with SHA-256 to produce a deterministic seed — so you always get the <strong>same 5 fictional employees</strong>, and your files never collide with another participant&#39;s. Output goes to <code>HR_DUPONT/</code> and the target repository path is <code>/BOB_LAB/DUPONT/</code>.</p><hr><h5 id="your-5-employees" tabindex="-1">Your 5 employees <a class="header-anchor" href="#your-5-employees" aria-label="Permalink to “Your 5 employees”">​</a></h5><table tabindex="0"><thead><tr><th>#</th><th>ID</th><th>Name</th><th>Department</th><th>Role</th></tr></thead><tbody><tr><td>1</td><td>DUP001</td><td>Antoine Muller</td><td>Human Resources</td><td>HR Specialist</td></tr><tr><td>2</td><td>DUP002</td><td>Lina Girard</td><td>Finance</td><td>Financial Analyst</td></tr><tr><td>3</td><td>DUP003</td><td>Lucas Mercier</td><td>Marketing</td><td>Marketing Manager</td></tr><tr><td>4</td><td>DUP004</td><td>Mia Renard</td><td>IT</td><td>Senior Developer</td></tr><tr><td>5</td><td>DUP005</td><td>Amira Dubois</td><td>Sales</td><td>Sales Representative</td></tr></tbody></table><hr><h5 id="cli-parameters" tabindex="-1">CLI parameters <a class="header-anchor" href="#cli-parameters" aria-label="Permalink to “CLI parameters”">​</a></h5><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--user LASTNAME</code></td><td>Set the lab namespace non-interactively (e.g. <code>DUPONT</code>)</td></tr><tr><td><code>--seed-misclassifications</code></td><td>Inject 5 deliberate errors for Lab 3</td></tr><tr><td><code>--dry-run</code></td><td>Preview what would be generated without writing any files</td></tr><tr><td><code>--employee N</code></td><td>Generate documents for only one employee (1-based index)</td></tr></tbody></table><hr><h5 id="the-5-seeded-errors-lab-3" tabindex="-1">The 5 seeded errors (Lab 3) <a class="header-anchor" href="#the-5-seeded-errors-lab-3" aria-label="Permalink to “The 5 seeded errors (Lab 3)”">​</a></h5><table tabindex="0"><thead><tr><th>Employee</th><th>Document</th><th>Error</th></tr></thead><tbody><tr><td>DUP001 Antoine Muller</td><td><code>DUP001_Payslip_2024_01.txt</code></td><td>Uploaded as base <code>Document</code> class — no EmployeeID</td></tr><tr><td>DUP002 Lina Girard</td><td><code>DUP002_Employment_Contract.txt</code></td><td>Wrong class (<code>Contract</code> instead of <code>HRDocument</code>), missing Department</td></tr><tr><td>DUP003 Lucas Mercier</td><td><code>DUP003_Performance_Review_2024.txt</code></td><td>Wrong EmployeeID (<code>000000</code> instead of <code>DUP003</code>)</td></tr><tr><td>DUP004 Mia Renard</td><td><code>DUP004_Disciplinary_Record.txt</code></td><td>Uploaded as base <code>Document</code> class — no metadata at all</td></tr><tr><td>DUP005 Amira Dubois</td><td><code>DUP005_Exit_Notes.txt</code></td><td>Correct class but missing <code>Department</code> and <code>DocType</code></td></tr></tbody></table><p>These are the documents Bob will need to detect and fix in the Lab 3 reclassification exercise.</p></div><h2 id="💬-follow-up-prompt-to-bob" tabindex="-1">💬 Follow-up Prompt to Bob <a class="header-anchor" href="#💬-follow-up-prompt-to-bob" aria-label="Permalink to “💬 Follow-up Prompt to Bob”">​</a></h2><ol><li>After the <code>generate_hr_documents.py</code> script successfully completed, enter the following prompt:<div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Show me what employees were generated</span></span></code></pre></div></li></ol><h2 id="✅-expected-output-from-bob-1" tabindex="-1">✅ Expected Output from Bob <a class="header-anchor" href="#✅-expected-output-from-bob-1" aria-label="Permalink to “✅ Expected Output from Bob”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The employee list was already printed in the previous run output. Here it is:</p><table tabindex="0"><thead><tr><th>#</th><th>ID</th><th>Name</th><th>Department</th><th>Role</th></tr></thead><tbody><tr><td>1</td><td>DUP001</td><td>Antoine Muller</td><td>Human Resources</td><td>HR Specialist</td></tr><tr><td>2</td><td>DUP002</td><td>Lina Girard</td><td>Finance</td><td>Financial Analyst</td></tr><tr><td>3</td><td>DUP003</td><td>Lucas Mercier</td><td>Marketing</td><td>Marketing Manager</td></tr><tr><td>4</td><td>DUP004</td><td>Mia Renard</td><td>IT</td><td>Senior Developer</td></tr><tr><td>5</td><td>DUP005</td><td>Amira Dubois</td><td>Sales</td><td>Sales Representative</td></tr></tbody></table><p>5 employees total, all fictional and deterministically derived from the <code>DUPONT</code> namespace seed.</p></div><h2 id="💡-key-insights" tabindex="-1">💡 Key Insights <a class="header-anchor" href="#💡-key-insights" aria-label="Permalink to “💡 Key Insights”">​</a></h2><p>You didn&#39;t need to read the Python source, look up the CLI flags, or figure out the right command to run — you just described what you wanted in plain language. This is the core shift that AI coding agents like IBM Bob enable: the mental overhead of <em>how to run a tool</em> is replaced by simply stating <em>what you need</em>. The same principle applies throughout this lab.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};